-- PT110-S2-Q20. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT110-S2-Q20$batch10$ AND q.stimulus=$batch10$Professor Chan: The literature department's undergraduate courses should cover only true literary works, and not such frivolous material as advertisements.

Professor Wigmore: Advertisements might or might not be true literary works but they do have a powerfully detrimental effect on society-largely because people cannot discern their real messages. The literature department's courses give students the critical skills to analyze and understand texts. Therefore, it is the literature department's responsibility to include the study of advertisements in its undergraduate courses.$batch10$ AND q.prompt=$batch10$Which one of the following principles most strongly supports Professor Wigmore's argument?$batch10$ AND q.correct_choice=$batch10$D$batch10$) THEN RAISE EXCEPTION 'Question changed: PT110-S2-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT110-S2-Q20$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S2-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT110-S2-Q20$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The literature department should include the study of advertisements in its undergraduate courses.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Advertisements have a harmful effect on society, largely because people can't discern their real messages. The department's courses give students the critical skills to analyze and understand texts.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$Wigmore leaves aside whether ads are literature. The reasoning is about harm and skills: ads do damage that the department's skills could counter. The principle should link "a text that can harm society" to "the department's courses should equip students to analyze it."$batch10$), (3, $batch10$Goal$batch10$, $batch10$If a text could harm society, the literature department's courses should help students analyze and understand it.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT110-S2-Q20$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This tells advertisers how to write ads. Wigmore's conclusion is about what the literature department should teach.$batch10$), ($batch10$B$batch10$, $batch10$Wigmore explicitly sets aside whether ads are literature ("might or might not be"). This answer argues that ads are literature, which is the issue Chan raised, and it doesn't connect to the harm Wigmore relies on.$batch10$), ($batch10$C$batch10$, $batch10$This says students should take a critical-skills course. It doesn't say that course has to cover advertisements, or that the literature department should teach it.$batch10$), ($batch10$D$batch10$, $batch10$Ads are texts that harm society, and this principle says the department's courses ought to equip students to analyze any such text. That leads straight to including ads in those courses.$batch10$), ($batch10$E$batch10$, $batch10$If each professor is free to choose the material, the department doesn't have a responsibility to include ads. That cuts against Wigmore.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT110-S2-Q20$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
